#!/usr/bin/env bash
# Applies Collabook settings to the Android files generated by `flutter create`.
set -euo pipefail
python3 tool/patch_android.py
echo "--- build.gradle signing"
grep -n "signingConfig\|minSdk" android/app/build.gradle* || true
echo "--- manifest"
grep -n "label\|permission\|allowBackup" android/app/src/main/AndroidManifest.xml || true
